SunspecPointDef::SunspecPointDef(const char *json, size_t json_len)
    : json_{json}, json_len_{json_len}
{

    FieldRef type_field = find_field(json_, json_len_, "type");
    FieldRef value_field = find_field(json_, json_len_, "value");

    std::string_view type_str = type_field.found ? tok_sv(type_field.json, type_field.tok) : std::string_view{};
    bool has_value = value_field.found;
    long long value = has_value ? tok_int(value_field.json, value_field.tok) : 0;

    SunspecPointData type;
    resolve_data(type_str, has_value, value, type, data_cache_);
}

std::string_view SunspecPointDef::id() const
{
    FieldRef f = find_field(json_, json_len_, "name");
    return f.found ? tok_sv(f.json, f.tok) : std::string_view{};
}

uint16_t SunspecPointDef::count() const
{
    FieldRef f = find_field(json_, json_len_, "count");
    if (!f.found)
    {
        return 1;
    }
    if (f.tok.type == JSMN_STRING)
    {
        return 0; // real count is looked up via count_point_id() at runtime
    }
    return static_cast<uint16_t>(tok_int(f.json, f.tok));
}

std::string_view SunspecPointDef::count_point_id() const
{
    FieldRef f = find_field(json_, json_len_, "count");
    return (f.found && f.tok.type == JSMN_STRING) ? tok_sv(f.json, f.tok) : std::string_view{};
}

int16_t SunspecPointDef::sf() const
{
    FieldRef f = find_field(json_, json_len_, "sf");
    if (!f.found || f.tok.type == JSMN_STRING)
    {
        return 0;
    }
    return static_cast<int16_t>(tok_int(f.json, f.tok));
}

std::string_view SunspecPointDef::sf_id() const
{
    FieldRef f = find_field(json_, json_len_, "sf");
    return (f.found && f.tok.type == JSMN_STRING) ? tok_sv(f.json, f.tok) : std::string_view{};
}

std::string_view SunspecPointDef::units() const
{
    FieldRef f = find_field(json_, json_len_, "units");
    return f.found ? tok_sv(f.json, f.tok) : std::string_view{};
}

std::string_view SunspecPointDef::label() const
{
    FieldRef f = find_field(json_, json_len_, "label");
    return f.found ? tok_sv(f.json, f.tok) : std::string_view{};
}

SunspecPointData SunspecPointDef::data_type() const
{
    return data_cache_.index() == 0 ? SunspecPointData_NONE : static_cast<SunspecPointData>(data_cache_.index());
}

